    for (i = 1; i < SIZE; i++) {
        has_errors |= data->a[i - 1] > data->a[i];
        data_sum += data->a[i];
        ref_sum += ref->a[i];
    }
    has_errors |= (data_sum != ref_sum);

    for (i = 0; i < SIZE; i++) {
        if (data->a[i] != ref->a[i]) {
            printf(
                "ERROR: data->a[%d] = %" PRId32 ", ref->a[%d] = %" PRId32 "\n",
                i,
